#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/util.h>

/* Define a structure for custom data */
struct k_thread_custom_data_test_data {
    int magic;
    struct k_sem cleanup_sem; /* Semaphore to signal cleanup completion */
};

/* Cleanup handler for custom data */
static void custom_data_cleanup(void *data) {
    struct k_thread_custom_data_test_data *d =
        (struct k_thread_custom_data_test_data *)data;

    /*
     * The page fault at 0x70023 suggests dereferencing a NULL pointer
     * with a large offset, or accessing an unmapped region.
     * This typically happens if 'data' is NULL and a member access like
     * 'd->member' is attempted, where 'member' is at offset 0x70023.
     *
     * Ensure 'data' is not NULL before attempting to dereference it.
     * The k_sem_give(&d->cleanup_sem) is a likely candidate for such a crash
     * if 'd' is NULL and 'cleanup_sem' is at offset 0x70023.
     */
    if (d != NULL) {
        k_sem_give(&d->cleanup_sem); /* Signal that cleanup has completed */
        k_free(d); /* Free the custom data structure itself */
    }
}

/* Test function for custom data cleanup helper */
static void test_custom_cleanup_helper(void) {
    struct k_thread_custom_data_test_data *data;

    /* Allocate memory for custom data */
    data = k_malloc(sizeof(struct k_thread_custom_data_test_data));
    if (data == NULL) {
        /* If allocation fails, skip the test to prevent NULL pointer issues */
        ztest_skip("Failed to allocate custom data");
        return;
    }

    /* Initialize custom data */
    data->magic = 0xDEADBEEF;
    k_sem_init(&data->cleanup_sem, 0, 1); /* Initialize the semaphore within the struct */

    /* Set custom data and cleanup handler for the current thread */
    k_thread_custom_data_set(data);
    k_thread_custom_data_cleanup_set(custom_data_cleanup);

    /*
     * The cleanup handler will be called when this thread exits.
     * We need to wait for the cleanup to complete before the test function returns,
     * to ensure the cleanup handler was indeed called and didn't crash.
     */
    k_sem_take(&data->cleanup_sem, K_FOREVER);

    /* If we reach here, cleanup completed without crashing (and the sem was given) */
    ztest_pass();
}

/* Other test functions for thread custom data */
static void test_custom_data_set_get(void) {
    int my_data = 123;
    void *ret_data;

    k_thread_custom_data_set(&my_data);
    ret_data = k_thread_custom_data_get();
    zassert_equal(ret_data, &my_data, "Custom data not retrieved correctly");

    /* Clear custom data for subsequent tests */
    k_thread_custom_data_set(NULL);
}

/* Define the test suite */
ZTEST_SUITE(thread_custom_data_suite, NULL, NULL, NULL, NULL, NULL);

ZTEST_UNIT_TEST(test_custom_data_set_get);
ZTEST_UNIT_TEST(test_custom_cleanup_helper);
